<script setup lang="ts">import { nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'; import * as echarts from 'echarts'; import type { ProvinceCount } from '@/types/domain'; const props = defineProps<{ data?: ProvinceCount }>(); const el = ref<HTMLElement>(); let chart: echarts.ECharts | undefined; function render() { if (!el.value) return; chart ??= echarts.init(el.value); chart.setOption({ grid: { left: 46, right: 15, top: 18, bottom: 25 }, tooltip: { trigger: 'axis' }, xAxis: { type: 'category', data: props.data?.provinces || [], axisLabel: { color: '#708895', fontSize: 11 } }, yAxis: { type: 'value', splitLine: { lineStyle: { color: '#edf4f2' } } }, series: [{ type: 'bar', barWidth: 18, data: props.data?.counts || [], itemStyle: { color: '#20a79a', borderRadius: [5, 5, 0, 0] } }] }); } onMounted(() => nextTick(render)); watch(() => props.data, render, { deep: true }); onBeforeUnmount(() => chart?.dispose())</script>
<template><div ref="el" class="chart chart--bar"></div></template>
